#include <juce_audio_utils/juce_audio_utils.h>
#include "ZAAudioImportRecipe.h"
#include <fstream>
#include <iostream>
using namespace za::fileimport;
namespace za::fileimport {struct ImportPreviewTestAccess {
 static void capture(ImportPreviewComponent& c,juce::File out){for(int i=0;i<2400&&(c.loading||c.pendingPreview);++i)juce::MessageManager::getInstance()->runDispatchLoopUntil(10);if(!c.source||c.loading)throw std::runtime_error("Preview failed");auto s=out.createOutputStream();s->setPosition(0);s->truncate();juce::PNGImageFormat().writeImageToStream(c.createComponentSnapshot(c.getLocalBounds()),*s);}
 static void studio(ImportPreviewComponent& c,juce::File out,const juce::AudioBuffer<float>& expected){
   capture(c,out.getChildFile("studio-balanced.png"));if(c.source->audio.buffer.getNumSamples()!=expected.getNumSamples())throw std::runtime_error("Combined length differs");for(int ch=0;ch<expected.getNumChannels();++ch)for(int i=0;i<expected.getNumSamples();++i)if(c.source->audio.buffer.getSample(ch,i)!=expected.getSample(ch,i))throw std::runtime_error("Combined source changed the input audio");
   c.presetSelector.setSelectedId(3,juce::sendNotificationSync);capture(c,out.getChildFile("studio-gestures.png"));
   auto obj=juce::var(new juce::DynamicObject());juce::Array<juce::var> regions;for(const auto&r:c.previewSegments){auto v=juce::var(new juce::DynamicObject());v.getDynamicObject()->setProperty("start",r.startSample/c.source->audio.sampleRate);v.getDynamicObject()->setProperty("end",r.endSample/c.source->audio.sampleRate);regions.add(v);}obj.getDynamicObject()->setProperty("regions",regions);obj.getDynamicObject()->setProperty("rate",c.source->audio.sampleRate);obj.getDynamicObject()->setProperty("samples",c.source->audio.buffer.getNumSamples());obj.getDynamicObject()->setProperty("preset","Whole gestures");out.getChildFile("gestures.json").replaceWithText(juce::JSON::toString(obj));
   for(int section=0;section<4;++section){c.section=section;c.resized();capture(c,out.getChildFile("wide-page-"+juce::String(section)+".png"));}
   c.section=0;c.advancedOpen=true;c.resized();capture(c,out.getChildFile("wide-advanced.png"));c.advancedOpen=false;
   c.sourcesOpen=true;c.resized();capture(c,out.getChildFile("wide-files.png"));c.sourcesOpen=false;
   c.waveform.fitSelection(c.previewSegments.front().startSample,c.previewSegments.front().endSample);c.resized();capture(c,out.getChildFile("wide-gesture-close.png"));c.waveform.fitAll();
   for(auto size:{juce::Point<int>(960,640),juce::Point<int>(720,520)}){c.setSize(size.x,size.y);for(int page=0;page<4;++page){c.section=page;c.resized();capture(c,out.getChildFile(juce::String(size.x)+"-page-"+juce::String(page)+".png"));if(page==0&&c.controls.getHeight()>c.controlsViewport.getHeight())throw std::runtime_error("Main detection page still needs scrolling");}}
   std::cout<<"PASS joined source equals direct concatenation, "<<c.previewSegments.size()<<" gesture proposals; wide and compact pages captured\n";
 }
};}
static void floatWave(const juce::AudioBuffer<float>&b,double rate,juce::File f){std::ofstream out(f.getFullPathName().toStdString(),std::ios::binary);auto u32=[&](uint32_t v){out.write((char*)&v,4);};auto u16=[&](uint16_t v){out.write((char*)&v,2);};uint32_t bytes=uint32_t(b.getNumSamples())*b.getNumChannels()*4;out.write("RIFF",4);u32(bytes+36);out.write("WAVEfmt ",8);u32(16);u16(3);u16(uint16_t(b.getNumChannels()));u32(uint32_t(rate));u32(uint32_t(rate)*b.getNumChannels()*4);u16(uint16_t(b.getNumChannels()*4));u16(32);out.write("data",4);u32(bytes);for(int i=0;i<b.getNumSamples();++i)for(int ch=0;ch<b.getNumChannels();++ch){float v=b.getSample(ch,i);out.write((char*)&v,4);}}
int main(int argc,char**argv)try{if(argc!=3)throw std::runtime_error("folder and output required");juce::ScopedJuceInitialiser_GUI gui;juce::File dir(argv[1]),out(argv[2]);out.createDirectory();auto files=dir.findChildFiles(juce::File::findFiles,false,"*.wav");files.sort();juce::AudioBuffer<float> combined;double rate=0;ImportRules raw;raw.gapMs=0;raw.crossfadeMs=0;juce::Array<juce::var> joins;for(const auto&f:files){juce::String error;auto data=readAudioFile(f,0,rate,0,error);if(!data)throw std::runtime_error(error.toStdString());rate=data->sampleRate;joins.add(combined.getNumSamples()/rate);appendBuffer(combined,data->buffer,rate,raw);}auto wav=out.getChildFile("combined-source.wav");floatWave(combined,rate,wav);auto a=extractor::analyse(audioView(combined,rate));auto d=extractor::detectAdaptive(audioView(combined,rate),a,{});juce::Array<juce::var> regions;int shortCount=0;for(const auto&r:d.regions){auto o=juce::var(new juce::DynamicObject());o.getDynamicObject()->setProperty("start",r.start/rate);o.getDynamicObject()->setProperty("end",r.end/rate);regions.add(o);shortCount+=r.end-r.start<rate*.08;}auto o=juce::var(new juce::DynamicObject());auto*p=o.getDynamicObject();p->setProperty("seconds",combined.getNumSamples()/rate);p->setProperty("rate",rate);p->setProperty("files",files.size());p->setProperty("regions",regions);p->setProperty("source_joins",joins);p->setProperty("under_80ms",shortCount);out.getChildFile("baseline.json").replaceWithText(juce::JSON::toString(o));std::ofstream frames(out.getChildFile("energy.csv").getFullPathName().toStdString());frames<<"time,energy,noise,onset\n";for(int i=0;i<int(a.frames.size());++i)frames<<a.sampleAt(i)/rate<<','<<a.frames[i].energyDb<<','<<a.frames[i].noiseDb<<','<<a.frames[i].onset<<'\n';auto rules=makeDefaultRulesForAction(ImportAction::SegmentLongFile);std::vector<juce::File> inputs; for(const auto& f:files)inputs.push_back(f); ImportPreviewComponent c(inputs,ImportAction::SegmentLongFile,rules,[](ImportRules){},[](juce::AudioBuffer<float>,double){},[]{},[](bool){});c.addToDesktop(juce::ComponentPeer::windowHasTitleBar);c.setTopLeftPosition(-16000,-16000);c.setVisible(true);ImportPreviewTestAccess::studio(c,out,combined);std::cout<<files.size()<<" parts, "<<combined.getNumSamples()/rate<<" seconds at "<<rate<<" Hz, "<<d.regions.size()<<" regions ("<<shortCount<<" under 80 ms)\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
